import re
ANCHOR = re.compile(r'look at the (given )?pictures?|pictures? below', re.I)


def place(lines):
    """Index to insert the pictures: after the first sentence that introduces them (after its box if it is
    inside one; inside an exercise it goes right under the question); otherwise after the @deco line."""
    depth_box = depth_ex = 0
    for i, l in enumerate(lines):
        if l.startswith('box '):
            depth_box += 1
        elif l.startswith('endbox'):
            depth_box -= 1
        elif l.startswith('exercise'):
            depth_ex += 1
        elif l.startswith('endexercise'):
            depth_ex -= 1
        elif ANCHOR.search(l.split('||')[0]) and l[:2] in ('p ', '- ', 'q '):
            if depth_box and not depth_ex:
                j = next(k for k in range(i, len(lines)) if lines[k].startswith('endbox'))
                return j + 1
            return i + 1
    return next(i for i, l in enumerate(lines) if l.startswith('@deco')) + 1


for page, figs in P.items():
    f = PAGES / f'{page}.txt'
    lines = [l for l in f.read_text(encoding='utf-8').splitlines() if not l.startswith('fig pic ')]
    at = place(lines)
    lines[at:at] = [f'fig pic {s} || {en} || {ur} || {ps}' for s, en, ur, ps in figs]
    f.write_text(chr(10).join(lines) + chr(10), encoding='utf-8')
print(len(P), 'pages,', sum(len(v) for v in P.values()), 'pictures')
